using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// 1) Strongly-typed retrieval — returns JsonTypeInfo<Person> directly.
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"Got typed metadata: {personInfo.Type.Name}");

// Round-trip to prove it works:
var json = JsonSerializer.Serialize(new Person("Ada", 38), personInfo);
Person deserialized = JsonSerializer.Deserialize(json, personInfo)!;
Console.WriteLine($"Round-trip: {deserialized}");

// 2) Probe without throwing — TryGetTypeInfo returns false when
//    metadata isn't available instead of throwing.
//    Here we use an options instance with NO resolver, so nothing resolves.
var empty = new JsonSerializerOptions { TypeInfoResolver = null };

if (empty.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? probed))
{
    Console.WriteLine($"Found metadata: {probed!.Type.Name}");
}
else
{
    Console.WriteLine("Metadata not available — no exception thrown.");
}

public record Person(string Name, int Age);

